function indicator(msg,tone='ok'){const el=$('syncIndicator');if(!el)return;el.textContent=msg;el.style.color=tone==='error'?'#ff8a8a':tone==='warn'?'#f5a623':'#d7e0ff';el.style.borderTopColor=tone==='error'?'#5c1f1f':tone==='warn'?'#5c4b1f':'rgba(124,156,255,.24)';el.style.background=tone==='error'?'rgba(38,14,14,.97)':tone==='warn'?'rgba(38,27,14,.97)':'rgba(13,13,13,.94)';el.classList.add('show');el.style.transform='translateY(0)';clearTimeout(indicator.t);indicator.t=setTimeout(()=>{el.classList.remove('show');el.style.transform='translateY(100%)'},1800)}
