function notifSettingsRow(){return{user_id:user.id,enabled:!!notifSettings.enabled,morning_enabled:!!notifSettings.morningEnabled,morning_time:notifSettings.morningTime||'08:00',evening_enabled:!!notifSettings.eveningEnabled,evening_time:notifSettings.eveningTime||'20:00'}}
function weekdayCountForRange(start,end){return tasks.filter(t=>t.category==='work'&&!t.done&&!t.blocked&&t.scheduledDate&&t.scheduledDate>=start&&t.scheduledDate<=end).length}
function todayNotificationData(){const tk=today(),{start,end}=getWeekWindow();const completedToday=reportPool().filter(t=>doneDate(t)===tk);const blockedToday=tasks.filter(t=>t.category==='work'&&t.blocked&&(t.scheduledDate===tk||key(t.updatedAt)===tk));const openToday=tasks.filter(t=>t.category==='work'&&!t.done&&!t.blocked&&t.scheduledDate===tk);return{todayCount:openToday.length+blockedToday.length,weekCount:weekdayCountForRange(start,end),doneCount:completedToday.length,blockedCount:blockedToday.length,pendingCount:openToday.length,activityCount:completedToday.length+blockedToday.length+openToday.length}}
function updateNotifUI(){const row=$('notifSettingsRow'),times=$('notifTimesRow');if(!row||!times)return;const perm=notifPermission();if(!notificationSupported()){row.innerHTML='<div class="settings-hint">This browser does not support reminders.</div>';times.style.display='none';return}if(notifTableMissing){row.innerHTML='<div class="settings-hint">Notifications need one-time cloud setup before synced reminders can be used.</div>';times.style.display='none';return}if(!user){row.innerHTML='<div class="settings-hint">Sign in to sync reminder preferences across devices.</div>';times.style.display='none';return}const masterOn=!!notifSettings.enabled;const permText=perm==='granted'?'Browser permission granted':perm==='denied'?'Browser permission blocked':'Browser permission not requested';const retryBtn=perm==='denied'?'<button class="btn-sm" type="button" id="notifRetryBtn">Retry Permission</button>':'';row.innerHTML=`<div class="workflow-row"><div class="toggle-switch ${masterOn?'on':''}" id="notifMasterToggle"><div class="toggle-knob"></div></div><span class="settings-hint" style="flex:1">Weekday reminders</span><span class="settings-hint">${esc(permText)}</span>${retryBtn}</div>`;$('notifMasterToggle')?.addEventListener('click',toggleNotifMaster);$('notifRetryBtn')?.addEventListener('click',requestNotifPermission);$('morningToggle')?.classList.toggle('on',masterOn&&!!notifSettings.morningEnabled);$('eveningToggle')?.classList.toggle('on',masterOn&&!!notifSettings.eveningEnabled);if($('morningTime'))$('morningTime').value=notifSettings.morningTime||'08:00';if($('eveningTime'))$('eveningTime').value=notifSettings.eveningTime||'20:00';times.style.display=masterOn?'flex':'none';if($('morningTime'))$('morningTime').disabled=!masterOn||!notifSettings.morningEnabled;if($('eveningTime'))$('eveningTime').disabled=!masterOn||!notifSettings.eveningEnabled}
async function persistNotifSettings(){if(!user||notifTableMissing)return;const {error}=await sb().from(NOTIF_TABLE).upsert(notifSettingsRow(),{onConflict:'user_id'});if(error){if(isNotifTableMissingError(error)){notifTableMissing=true;updateNotifUI();scheduleNotifications();return}throw error}}
